SELECT p.PartiNo, p.PartiKodu AS Parti, Format(p.Tarih,"dd.mm.yyyy") AS Kabul, m.AdSoyad AS Müşteri, p.OdemeTipi AS Ödeme, Format(Nz(p.MusteriKalanYag_Kg,0),"#,##0.00") AS [Net Yağ], Format(p.TeslimTarihi,"dd.mm.yyyy") AS [Teslim Tarihi], p.TeslimAlan AS [Teslim Alan], Format(p.TeslimYag_Kg,"#,##0.00") AS [Teslim Edilen], IIf(p.OdemeTipi Like "S*",Format(Nz(p.TLTutari,0),"#,##0.00"),"-") AS Ücret, IIf(p.OdemeTipi Like "S*",Format(Nz(b.Kalan,0),"#,##0.00"),"-") AS [Kalan Borç], IIf(p.TeslimTarihi Is Null,"Bekliyor","Teslim Edildi") AS Durum, p.TeslimTarihi AS TeslimTarihiHam, p.Sezon, p.Tarih AS PartiTarihiHam, Val(Nz(p.PartiKodu,"0")) AS PartiSira, Nz(b.Kalan,0) AS KalanHam
FROM (tbl_Parti AS p LEFT JOIN tbl_Musteri AS m ON p.MusteriID=m.MusteriID) LEFT JOIN qry_PartiBakiye AS b ON p.PartiNo=b.PartiNo
WHERE p.SikimTarihi Is Not Null AND Nz(p.CikanYag_Kg,0)>0;